import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing the same algorithm as the CuTe/CUDA kernel:
#   - grid = (1, ceil(Cout/OC_PER_BLOCK), N)
#   - block = (THREADS, 1, 1)
#   - each block caches OC_PER_BLOCK output-channel filters into shared mem
#   - each thread strides over output pixels (oh, ow) and accumulates
#     OC_PER_BLOCK partial sums directly from global memory
# ---------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.extern .shared .align 16 .b8 smem_raw[];

.visible .entry conv2d_kernel(
    .param .u64 p_X,
    .param .u64 p_W,
    .param .u64 p_B,
    .param .u64 p_Y,
    .param .u32 p_N,
    .param .u32 p_Cin,
    .param .u32 p_H,
    .param .u32 p_Win,
    .param .u32 p_Cout,
    .param .u32 p_K,
    .param .u32 p_stride,
    .param .u32 p_padding,
    .param .u32 p_Hout,
    .param .u32 p_Wout
)
{
    .reg .pred %p<20>;
    .reg .b32 %r<70>;
    .reg .b64 %rd<40>;
    .reg .f32 %f<40>;

    ld.param.u64 %rd1, [p_X];
    ld.param.u64 %rd2, [p_W];
    ld.param.u64 %rd3, [p_B];
    ld.param.u64 %rd4, [p_Y];
    ld.param.u32 %r1, [p_N];
    ld.param.u32 %r2, [p_Cin];
    ld.param.u32 %r3, [p_H];
    ld.param.u32 %r4, [p_Win];
    ld.param.u32 %r5, [p_Cout];
    ld.param.u32 %r6, [p_K];
    ld.param.u32 %r7, [p_stride];
    ld.param.u32 %r8, [p_padding];
    ld.param.u32 %r9, [p_Hout];
    ld.param.u32 %r10, [p_Wout];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r11, %ctaid.z;
    mov.u32 %r12, %ctaid.y;
    mov.u32 %r13, %tid.x;
    mov.u32 %r14, %ntid.x;

    mov.u32 %r15, 4;
    mul.lo.s32 %r16, %r12, %r15;

    mul.lo.s32 %r17, %r2, %r6;
    mul.lo.s32 %r17, %r17, %r6;
    mul.lo.s32 %r18, %r17, %r15;
    mul.lo.s32 %r19, %r6, %r6;

    mov.u32 %r20, smem_raw;

    mov.u32 %r21, %r13;
LOOP_W:
    setp.ge.s32 %p1, %r21, %r18;
    @%p1 bra LOOP_W_DONE;

    div.s32 %r22, %r21, %r17;
    rem.s32 %r23, %r21, %r17;
    div.s32 %r24, %r23, %r19;
    rem.s32 %r25, %r23, %r19;
    div.s32 %r26, %r25, %r6;
    rem.s32 %r27, %r25, %r6;

    add.s32 %r28, %r16, %r22;

