class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.empty(out_channels))

        self.reset_parameters(in_channels, kernel_size)

        self._module = None

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = in_channels * kernel_size * kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def _get_module(self):
        if self._module is None:
            self._module = PtxModule(PTX_SOURCE)
        return self._module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be on CUDA device"

        module = self._get_module()

        x_c = x.contiguous()
        w_c = self.weight.contiguous()
        b_c = self.bias.contiguous()

        N, Cin, H, Win = x_c.shape
        Cout, _, K, _ = w_c.shape
        stride = self.stride
        padding = self.padding

        Hout = (H + 2 * padding - K) // stride + 1
        Wout = (Win + 2 * padding - K) // stride + 1
        assert Hout > 0 and Wout > 0, "invalid computed output size"

        y = torch.empty((N, Cout, Hout, Wout), device=x_c.device, dtype=x_c.dtype)

        grid = (
            (Hout + _TILE_OH - 1) // _TILE_OH,
            (Cout + _OC_PER_BLOCK - 1) // _OC_PER_BLOCK,
            N,
        )
        block = (_THREADS, 1, 1)

        in_tile_h = (_TILE_OH - 1) * stride + K
        weight_bytes = _OC_PER_BLOCK * Cin * K * K * 4
        input_tile_bytes = Cin * in_tile_h * Win * 4
        shared_mem_bytes = weight_bytes + input_tile_bytes

        stream = torch.cuda.current_stream(x_c.device).cuda_stream

        module.launch(
            _ENTRY_NAME,
            grid=grid,
            block=block,
            shared_mem_bytes=shared_mem_bytes,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(b_c.data_ptr()),
                u64(y.data_ptr()),
                i32(N),
                i32(Cin),
                i32(H),
                i32(Win),
                i32(Cout),
                i32(K),
                i32(stride),
                i32(padding),
                i32(Hout),
                i32(Wout),
            ],
        )

        return y

